  "scripts": {
    "dev": "vite",
    "build:wasm": "node build-wasm.js",
    "build": "npm run build:wasm && vite build",
    "postbuild": "node copy-config.js",
    "preview": "vite preview"
  },
  "dependencies": {
    "three": "^0.160.0",
    "terser": "^5.44.1"
  },
  "devDependencies": {
    "terser": "^5.44.1",
    "vite": "^5.0.0",
    "assemblyscript": "^0.27.0"
  }
}

import { defineConfig } from 'vite';

export default defineConfig({
  envPrefix: ['VITE_', 'CLIENT_'],
  build: {
    outDir: 'dist',
    assetsDir: 'assets',
    sourcemap: false,
    minify: 'terser',
    terserOptions: {
      compress: {
        drop_console: false
      }
    },
    rollupOptions: {
      output: {
        // Ensure WASM files are copied to dist root
        assetFileNames: (assetInfo) => {
          if (assetInfo.name && assetInfo.name.endsWith('.wasm')) {
            return '[name][extname]';
          }
          return 'assets/[name]-[hash][extname]';
        }
      }
    }
  },
  server: {
    port: 3000,
    open: true
  }
});

