import json
from pathlib import Path
from typing import Dict, Any


class MetaController:
    """
    Monitors subsystem metrics and emits meta decisions (planning mode, temps, step budgets).
    """

    def __init__(self, root: Path) -> None:
        self.root = root
        self.state_path = root / "data" / "sandbox" / "tmp" / "meta_state.json"
        self.state_path.parent.mkdir(parents=True, exist_ok=True)

    def _read_json(self, p: Path) -> Dict[str, Any]:
        try:
            return json.loads(p.read_text(encoding="utf-8"))
        except Exception:
            return {}

    def read_metrics(self) -> Dict[str, Any]:
        wm = self._read_json(self.root / "models" / "wm_mlp" / "metrics.json")
        vf = self._read_json(self.root / "models" / "verifier_calib" / "metrics.json")
        return {"wm": wm, "verifier": vf}

    def decide(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        wm_ece = float(metrics.get("wm", {}).get("wm_ece", 0.5) or 0.5)
        cal_ece = float(metrics.get("verifier", {}).get("cal_ece", 0.5) or metrics.get("verifier", {}).get("base_ece", 0.5) or 0.5)
        # Heuristics
        enable_tot = (cal_ece > 0.2) or (wm_ece > 0.25)...

